-- 0013: safe client/partner projections and restricted raw grants.
revoke select on buzzerhood.campaigns,buzzerhood.campaign_partner_assignments,buzzerhood.campaign_deliverables,buzzerhood.content_submissions,buzzerhood.content_submission_reviews,buzzerhood.publications,buzzerhood.publication_metric_snapshots from authenticated;
create or replace view buzzerhood.client_campaigns as select c.id,c.organization_id,c.name,c.reference_code,c.status,c.objective_summary,c.planned_start,c.planned_end,c.currency,c.created_at,c.updated_at from buzzerhood.campaigns c where buzzerhood.is_active_organization_member(c.organization_id) or buzzerhood.has_permission('campaigns.read');
create or replace view buzzerhood.client_campaign_briefs as select b.* from buzzerhood.campaign_briefs b join buzzerhood.client_campaigns c on c.id=b.campaign_id;
create or replace view buzzerhood.client_campaign_assignments as select a.id,a.campaign_id,a.partner_id,a.status,a.invited_at,a.responded_at,a.accepted_at from buzzerhood.campaign_partner_assignments a join buzzerhood.client_campaigns c on c.id=a.campaign_id;
create or replace view buzzerhood.client_campaign_deliverables as select d.id,d.assignment_id,d.title,d.description,d.platform,d.due_date,d.quantity,d.status,d.created_at,d.updated_at from buzzerhood.campaign_deliverables d join buzzerhood.client_campaign_assignments a on a.id=d.assignment_id;
create or replace view buzzerhood.client_content_submissions as select s.id,s.deliverable_id,s.version,s.status,s.caption_body,s.concept_notes,s.asset_reference,s.content_url,s.submitted_at from buzzerhood.content_submissions s join buzzerhood.client_campaign_deliverables d on d.id=s.deliverable_id;
create or replace view buzzerhood.client_publications as select p.id,p.deliverable_id,p.content_submission_id,p.platform_account_id,p.publication_url,p.status,p.submitted_at,p.verified_at,p.verification_note from buzzerhood.publications p join buzzerhood.client_campaign_deliverables d on d.id=p.deliverable_id;
create or replace view buzzerhood.client_publication_metrics as select m.id,m.publication_id,m.metric_type,m.metric_value,m.period_start,m.period_end,m.source,m.captured_at,m.verification_note from buzzerhood.publication_metric_snapshots m join buzzerhood.client_publications p on p.id=m.publication_id;
create or replace view buzzerhood.partner_campaigns as select c.id,c.name,c.status,c.planned_start,c.planned_end,b.objective,b.description,b.target_audience,b.key_message,b.call_to_action,b.content_direction from buzzerhood.campaigns c join buzzerhood.campaign_briefs b on b.campaign_id=c.id join buzzerhood.campaign_partner_assignments a on a.campaign_id=c.id where buzzerhood.is_active_partner_member(a.partner_id);
create or replace view buzzerhood.partner_assignments as select a.id,a.campaign_id,a.partner_id,a.status,a.invited_at,a.responded_at,a.accepted_at,a.agreed_fee,a.fee_currency from buzzerhood.campaign_partner_assignments a where buzzerhood.is_active_partner_member(a.partner_id);
create or replace view buzzerhood.partner_deliverables as select d.id,d.assignment_id,d.title,d.description,d.platform,d.due_date,d.quantity,d.status,d.created_at,d.updated_at from buzzerhood.campaign_deliverables d join buzzerhood.partner_assignments a on a.id=d.assignment_id;
create or replace view buzzerhood.partner_content_submissions as select s.id,s.deliverable_id,s.version,s.status,s.caption_body,s.concept_notes,s.asset_reference,s.content_url,s.submitted_at from buzzerhood.content_submissions s join buzzerhood.partner_deliverables d on d.id=s.deliverable_id;
create or replace view buzzerhood.partner_publications as select p.id,p.deliverable_id,p.content_submission_id,p.platform_account_id,p.publication_url,p.status,p.submitted_at,p.verified_at,p.verification_note from buzzerhood.publications p join buzzerhood.partner_deliverables d on d.id=p.deliverable_id;
grant select on buzzerhood.client_campaigns,buzzerhood.client_campaign_briefs,buzzerhood.client_campaign_assignments,buzzerhood.client_campaign_deliverables,buzzerhood.client_content_submissions,buzzerhood.client_publications,buzzerhood.client_publication_metrics,buzzerhood.partner_campaigns,buzzerhood.partner_assignments,buzzerhood.partner_deliverables,buzzerhood.partner_content_submissions,buzzerhood.partner_publications to authenticated;
create or replace view buzzerhood.internal_campaigns as select c.* from buzzerhood.campaigns c where buzzerhood.has_permission('campaigns.read');
create or replace view buzzerhood.internal_campaign_assignments as select a.* from buzzerhood.campaign_partner_assignments a where buzzerhood.has_permission('campaigns.read');
create or replace view buzzerhood.internal_campaign_deliverables as select d.* from buzzerhood.campaign_deliverables d where buzzerhood.has_permission('campaigns.read');
create or replace view buzzerhood.internal_content_submissions as select s.* from buzzerhood.content_submissions s where buzzerhood.has_permission('campaigns.read');
create or replace view buzzerhood.internal_publications as select p.* from buzzerhood.publications p where buzzerhood.has_permission('campaigns.read');
grant select on buzzerhood.internal_campaigns,buzzerhood.internal_campaign_assignments,buzzerhood.internal_campaign_deliverables,buzzerhood.internal_content_submissions,buzzerhood.internal_publications to authenticated;
insert into buzzerhood.schema_migrations(version,filename) values('0013','0013_campaign_safe_projections.sql') on conflict(version) do nothing;
